/* v405: the extra shelf is a real shelf. Every case below is a distinct company or brand with its own researched rise, fall, mistake and lesson. No filler text, no duplicate graves wearing new serial numbers. */
window.FAILURES = (window.FAILURES || []).concat([{"id":"microsoft-kin","name":"Microsoft Kin","title":"Dead in about two months","year":"2010","category":"STARTUP","emoji":"📱","loss":"Axed weeks after launch","story":"Microsoft built Kin One and Kin Two for teenagers who lived in social feeds. The phones looked friendly, synced photos to the cloud early, and were sold through Verizon with real marketing muscle. The launch landed between worlds. Kin had no app store, weak smartphone features, and data pricing that made parents compare it with real smartphones. Sales were so poor that Microsoft cancelled the line roughly two months after launch and folded the team into Windows Phone.","mistake":"Selling a social phone that was neither cheap enough to be simple nor open enough to be smart.","lesson":"A narrow user does not excuse a narrow product. If buyers compare you with the stronger category beside you, you are in that category.","book":"crossing-chasm","bookTitle":"Crossing the Chasm"},{"id":"hp-touchpad","name":"HP TouchPad","title":"The 49 day tablet","year":"2011","category":"BUSINESS","emoji":"📲","loss":"Discontinued after 49 days","story":"HP bought Palm for webOS and rushed the TouchPad into the tablet race. The system had elegant cards and multitasking, and HP had retail reach most rivals would envy. The TouchPad arrived heavier, slower and priced like an iPad without the app library. Seven weeks after launch HP killed the product, fired the strategy around webOS hardware, and cleared stock in a famous fire sale that proved demand existed only at a loss-making price.","mistake":"Confusing ownership of a good operating system with a reason for customers to switch.","lesson":"Polish cannot rescue timing, price and ecosystem when all three point the wrong way.","book":"innovators-dilemma","bookTitle":"The Innovator's Dilemma"},{"id":"turntable-fm","name":"Turntable.fm","title":"The room went quiet","year":"2013","category":"STARTUP","emoji":"🎧","loss":"Music service closed in 2013","story":"Turntable.fm turned listening into a social room where avatars took turns as DJs. Music fans loved the feeling of playing records for strangers who reacted in real time. The fun depended on music licences that were expensive and geographically messy. Growth cooled, the mobile shift raised costs, and the company shut the music rooms in 2013 to chase a live events idea that never matched the original spark.","mistake":"Building a social habit on rights it could not afford to clear at scale.","lesson":"If your core delight needs permission, the permission is part of the product and part of the unit economics.","book":"lean-startup","bookTitle":"The Lean Startup"},{"id":"periscope","name":"Periscope","title":"The live pioneer logs off","year":"2021","category":"STARTUP","emoji":"📹","loss":"App shut in 2021","story":"Periscope made phone livestreaming feel instant and public just as Meerkat created the moment. Twitter bought it before launch and gave it a huge audience door. Live video became a feature everywhere rather than a destination. Usage and economics weakened, spam and moderation costs stayed high, and Twitter closed the standalone app in 2021 while absorbing live tools into the main service.","mistake":"Mistaking a new behaviour for a durable standalone network.","lesson":"When platforms copy the feature and own the audience, a pioneer needs a second moat fast.","book":"crossing-chasm","bookTitle":"Crossing the Chasm"},{"id":"mixer","name":"Mixer","title":"Big streamers, small crowd","year":"2020","category":"BUSINESS","emoji":"🎮","loss":"Closed in 2020","story":"Microsoft bought Beam, renamed it Mixer, and tried to buy attention in game streaming with exclusive deals for stars such as Ninja and Shroud. The technology was fast and interactive. Viewers did not follow in enough numbers. Twitch and YouTube already held the communities, clips and habits, so expensive exclusives rented fame without creating a crowd. Microsoft shut Mixer in 2020 and sent partners toward Facebook Gaming.","mistake":"Trying to purchase a network effect one celebrity at a time.","lesson":"An audience is not a pile of followers. It is the place people already gather.","book":"blue-ocean-strategy","bookTitle":"Blue Ocean Strategy"},{"id":"livingsocial","name":"LivingSocial","title":"The daily deal that faded","year":"2016","category":"STARTUP","emoji":"🎟️","loss":"Sold to its rival in 2016","story":"LivingSocial rode the daily deal boom beside Groupon, selling restaurant, travel and experience vouchers to millions of subscribers. Amazon invested and the company expanded fast. The deals exhausted merchants, trained customers to wait for discounts, and produced low repeat value. After layoffs and asset sales, Groupon acquired LivingSocial in 2016 for no material consideration and the brand wound down.","mistake":"Growing a marketplace by teaching both sides to value it less.","lesson":"Discounts can start a market. They cannot be the whole relationship.","book":"profit-first","bookTitle":"Profit First"},{"id":"rdio","name":"Rdio","title":"Beautiful player, brutal market","year":"2015","category":"STARTUP","emoji":"🎵","loss":"Bankrupt in 2015","story":"Rdio was one of the best designed early streaming services, built by people who understood social listening. Critics praised it while Spotify raced ahead on free tiers, playlists and global deals. Streaming margins were thin and scale decided who could survive them. Rdio filed for bankruptcy in 2015 and sold key assets to Pandora, which later closed the service it tried to build from the remains.","mistake":"Winning taste while losing distribution and cash.","lesson":"In commodity content markets, design is a feature. Scale and rights are the business.","book":"crossing-chasm","bookTitle":"Crossing the Chasm"},{"id":"grooveshark","name":"Grooveshark","title":"Killed by the catalogue","year":"2015","category":"BUSINESS","emoji":"🦈","loss":"Shut after legal settlement","story":"Grooveshark let users upload and stream music before licensed streaming felt normal. It built a large audience by making almost any song feel available instantly. Labels argued that the catalogue depended on infringement. After years of lawsuits, Grooveshark shut in 2015 as part of a settlement and apologised to rights holders. The audience had been real, but the legal foundation was not.","mistake":"Letting growth outrun the licences that made growth possible.","lesson":"A shortcut through rights can look like product market fit until the bill arrives with lawyers attached.","book":"bad-blood","bookTitle":"Bad Blood"},{"id":"blip-tv","name":"Blip.tv","title":"Web series lost the front page","year":"2015","category":"STARTUP","emoji":"📺","loss":"Closed in 2015","story":"Blip.tv gave independent web shows hosting, ads and a home before YouTube fully professionalised online video. Many early creators treated it as the serious alternative for episodic work. YouTube owned discovery, embeds and advertiser gravity. Blip was sold to Maker Studios, then Disney absorbed Maker, and the service was closed in 2015 because a separate destination no longer made strategic sense.","mistake":"Depending on being the alternative to the platform that controlled demand.","lesson":"If discovery lives elsewhere, your home page is a warehouse, not a market.","book":"crossing-chasm","bookTitle":"Crossing the Chasm"},{"id":"justin-tv","name":"Justin.tv","title":"The parent died, the child won","year":"2014","category":"STARTUP","emoji":"📡","loss":"Closed to focus on Twitch","story":"Justin.tv began as one man broadcasting his life and opened lifecasting to anyone. It created the pipes, culture and audience habits that made live online video plausible. The strongest category inside it was games. Justin.tv spun that energy into Twitch, then closed the original site in 2014 so the company could become the thing viewers actually came for.","mistake":"Keeping the broad original brand alive after one narrow use case had clearly won.","lesson":"A pivot is not failure when the child is stronger. Feeding the old name out of sentiment is.","book":"lean-startup","bookTitle":"The Lean Startup"},{"id":"metacafe","name":"Metacafe","title":"Early video, late exit","year":"2021","category":"BUSINESS","emoji":"🎬","loss":"Site closed in 2021","story":"Metacafe was an early home for short entertainment clips when online video still felt new. It focused on entertainment rather than every possible upload. YouTube became the default verb for video and took creators, advertisers and search traffic. Metacafe survived for years as a smaller property, changed hands, and finally closed in 2021 after long decline.","mistake":"Trying to outlast a platform that had become the market itself.","lesson":"Being early helps only if early turns into habit, catalogue or community that cannot be copied by scale.","book":"innovators-dilemma","bookTitle":"The Innovator's Dilemma"},{"id":"gawker","name":"Gawker","title":"One lawsuit ended the empire","year":"2016","category":"FAME","emoji":"🗞️","loss":"Bankrupt and shut in 2016","story":"Gawker defined a snarky internet media era and built a profitable empire around gossip, media criticism and stories other outlets feared to touch. Its voice shaped a generation of digital writers. A privacy lawsuit backed by Peter Thiel over the Hulk Hogan sex tape produced a huge judgment. Gawker Media filed for bankruptcy, sold its other sites, and Gawker.com itself was shut in 2016.","mistake":"Treating legal and ethical risk as a brand asset until one case collected the debt.","lesson":"A business model that profits from enemies must price the day an enemy can fund the fight.","book":"bad-blood","bookTitle":"Bad Blood"},{"id":"village-voice","name":"Village Voice","title":"The alt weekly falls silent","year":"2018","category":"HISTORY","emoji":"📰","loss":"Publication suspended in 2018","story":"The Village Voice invented much of the American alternative weekly: fierce politics, arts coverage, classifieds and a city arguing with itself in print. For decades it was both a newspaper and a New York institution. The internet took classifieds, then ads, then the weekly habit. The paper ended print in 2017 and suspended publication in 2018 after ownership changes and staff cuts hollowed the thing readers loved.","mistake":"Assuming cultural importance would somehow pay the printer.","lesson":"Influence is not revenue unless someone builds the bridge between the two.","book":"mighty-fall","bookTitle":"How the Mighty Fall"},{"id":"q-magazine","name":"Q Magazine","title":"The music monthly closes","year":"2020","category":"FAME","emoji":"🎸","loss":"Closed after 34 years","story":"Q was the glossy British music magazine that treated albums as events. It survived the CD boom by selling authority, interviews and a monthly ritual for fans. Streaming made discovery instant and social feeds took the conversation. Print economics thinned for years, and the pandemic pushed the title into closure in 2020 despite its archive and brand love.","mistake":"Selling slow authority in a market that had moved to instant access.","lesson":"When the ritual changes, heritage becomes inventory unless it finds a new ritual.","book":"innovators-dilemma","bookTitle":"The Innovator's Dilemma"},{"id":"essential-products","name":"Essential Products","title":"One phone was not a company","year":"2020","category":"STARTUP","emoji":"📱","loss":"Closed in 2020","story":"Essential was founded by Android co-creator Andy Rubin and launched a beautifully made phone with a titanium body, magnetic accessories and enormous credibility. The PH-1 looked like a design statement. The phone sold poorly at a premium price, the camera disappointed, and follow up products never stabilised the company. Essential shut in 2020 after trying to turn one admired object into a platform.","mistake":"Believing pedigree and design could substitute for distribution, iteration speed and a second act.","lesson":"A first product proves taste. A company needs repeat purchase logic.","book":"hard-things","bookTitle":"The Hard Thing About Hard Things"},{"id":"a123-systems","name":"A123 Systems","title":"The battery champion runs flat","year":"2012","category":"BUSINESS","emoji":"🔋","loss":"Bankrupt in 2012","story":"A123 made advanced lithium iron phosphate batteries and became a clean tech star, supplying carmakers and winning government support. Electric vehicles seemed ready to reward exactly its technology. Costs stayed high, a costly Fisker battery recall hurt, and EV demand grew slower than the factories built for it. A123 filed for bankruptcy in 2012 and its assets were sold to Wanxiang.","mistake":"Building capacity for the adoption curve promised by headlines rather than signed demand.","lesson":"In hardware, optimistic demand is not a forecast. It is a loan you must repay in cash.","book":"black-swan","bookTitle":"The Black Swan"},{"id":"coda-automotive","name":"Coda Automotive","title":"The sensible EV nobody bought","year":"2013","category":"STARTUP","emoji":"🚗","loss":"Bankrupt in 2013","story":"Coda tried to sell a practical electric sedan adapted from a Chinese platform, aimed at buyers who wanted an EV without science fiction styling. It raised serious money and reached the market. The car looked dated beside the Nissan Leaf and the rising Tesla story, while range, price and dealer reach all worked against it. Sales were tiny and Coda filed for bankruptcy in 2013.","mistake":"Entering a technology transition with a product that felt like yesterday.","lesson":"In a new category, boring is only safe when it is much cheaper or much easier. Coda was neither.","book":"crossing-chasm","bookTitle":"Crossing the Chasm"},{"id":"aptera-original","name":"Aptera (original)","title":"The future car that never shipped","year":"2011","category":"STARTUP","emoji":"🛞","loss":"Original company liquidated in 2011","story":"The original Aptera promised a teardrop three wheeled electric car so efficient it looked like a small aircraft. Deposits and press followed the idea because the design made the future visible. Production kept slipping as the company chased loans, changed plans and tried to become more conventional. It liquidated in 2011 without delivering the car that had made people believe.","mistake":"Letting the dream design raise money faster than manufacturing reality could follow.","lesson":"A prototype can prove desire. Only production proves a car company.","book":"hard-things","bookTitle":"The Hard Thing About Hard Things"},{"id":"studebaker","name":"Studebaker","title":"A century ends quietly","year":"1966","category":"HISTORY","emoji":"🚙","loss":"Car production ended in 1966","story":"Studebaker began with wagons in the 1800s and became an American car name known for style and engineering. After the war it stood among the independents trying to survive beside Detroit giants. The Big Three could cut prices and refresh models at a scale Studebaker could not match. A merger with Packard did not create enough strength, US production ended in 1963 and the last cars rolled from Canada in 1966.","mistake":"Competing on craft where scale had become the weapon.","lesson":"When giants turn a craft market into a price war, independence needs a niche, not nostalgia.","book":"mighty-fall","bookTitle":"How the Mighty Fall"},{"id":"pontiac","name":"Pontiac","title":"The performance badge is parked","year":"2010","category":"BUSINESS","emoji":"🏎️","loss":"Brand retired in 2010","story":"Pontiac sold excitement inside General Motors: GTO, Firebird and a promise that driving should feel louder than commuting. For decades the badge gave GM a clear personality. Badge engineering diluted the promise until many Pontiacs felt like other GM cars with different trim. During GM bankruptcy restructuring, Pontiac was chosen for execution and the brand ended in 2010.","mistake":"Keeping the badge while draining the difference.","lesson":"A sub brand dies when customers can no longer say what it stands for in one sentence.","book":"good-strategy-bad-strategy","bookTitle":"Good Strategy Bad Strategy"},{"id":"oldsmobile","name":"Oldsmobile","title":"Your father's brand problem","year":"2004","category":"BUSINESS","emoji":"🚘","loss":"Phased out in 2004","story":"Oldsmobile was once a technology flagship inside GM and one of America's oldest car names. It sold millions by standing for attainable engineering and comfort. Its buyers aged and younger drivers chose imports or other GM badges. The famous attempt to say it was not your father's Oldsmobile admitted the problem without solving it, and GM phased the brand out in 2004.","mistake":"Marketing around an ageing customer base instead of earning a new one.","lesson":"A loyal base can hide a missing future for years. Then both disappear together.","book":"mighty-fall","bookTitle":"How the Mighty Fall"},{"id":"saturn","name":"Saturn","title":"A different kind of car company, absorbed","year":"2010","category":"BUSINESS","emoji":"🪐","loss":"Closed in 2010","story":"GM created Saturn as a fresh answer to Japanese imports: plastic panels, friendly dealers and no haggle pricing. Early owners formed a community that big car companies rarely earn. Saturn slowly became ordinary GM product with Saturn badges. When a sale to Penske failed during restructuring, GM shut the brand in 2010 and the experiment ended where it began, inside the parent it was meant to escape.","mistake":"Launching a rebel brand and then managing it back into sameness.","lesson":"Culture is a strategy only if headquarters protects it when budgets get tight.","book":"good-to-great","bookTitle":"Good to Great"},{"id":"saab-automobile","name":"Saab Automobile","title":"Born from jets, grounded by debt","year":"2011","category":"BUSINESS","emoji":"✈️","loss":"Bankrupt in 2011","story":"Saab cars were quirky, turbocharged and loved by people who disliked ordinary choices. Under GM the Swedish brand kept a loyal cult even as volumes stayed small. GM ownership diluted investment, the financial crisis hit, and a rescue by Spyker could not fund the next models. Saab Automobile filed for bankruptcy in 2011 after production stopped and suppliers went unpaid.","mistake":"Owning a beloved niche without the cash to keep it distinct.","lesson":"Cult love is valuable, but cult size must match the cost base built around it.","book":"mighty-fall","bookTitle":"How the Mighty Fall"},{"id":"mg-rover","name":"MG Rover","title":"The last volume British carmaker","year":"2005","category":"BUSINESS","emoji":"🚗","loss":"Collapsed in 2005","story":"MG Rover carried famous British badges and the Longbridge workforce into a post BMW independence story. Supporters hoped a Phoenix consortium could keep mass British car making alive. The model range aged, quality and investment lagged, and a hoped Chinese partnership arrived too late. The company collapsed in 2005 with thousands of jobs lost and the brands later scattered.","mistake":"Trying to fund a turnaround with heritage while the product line aged in public.","lesson":"National pride can open doors. It cannot refresh a car range.","book":"hard-things","bookTitle":"The Hard Thing About Hard Things"},{"id":"holden","name":"Holden","title":"Australia stops making its own","year":"2020","category":"HISTORY","emoji":"🦘","loss":"Brand retired in 2020","story":"Holden was more than a car badge in Australia. The Commodore became a national object, and local manufacturing made the brand part of the country's industrial identity. GM ended Australian production in 2017 as costs and market shifts made local manufacturing hard to defend. Without local cars the badge lost its centre, and GM retired Holden in 2020.","mistake":"Letting identity depend on a factory economics could no longer carry.","lesson":"When place is the brand, moving production is not a supply decision. It is a brand decision.","book":"mighty-fall","bookTitle":"How the Mighty Fall"},{"id":"clinton-cards","name":"Clinton Cards","title":"The card shop that forgot the calendar","year":"2012","category":"BUSINESS","emoji":"💌","loss":"Entered administration in 2012; hundreds of stores closed","story":"Clinton Cards made buying a birthday card feel like a British high street ritual, with hundreds of shops selling cards, gifts and celebration clutter for every family date. It owned the calendar in physical form. Supermarkets put cards beside the weekly shop, online services personalised and posted them, and Clinton carried too many expensive shops for a product with low baskets and seasonal spikes. The company entered administration in 2012 after its landlord and lenders lost patience; many stores closed and the brand survived only in reduced form.","mistake":"Owning hundreds of shops to sell small, seasonal items while supermarkets and online rivals made the same purchase easier.","lesson":"A ritual product still needs a modern route to the ritual. If the reminder lives on a phone, the shop cannot rely on being walked past.","book":"rework","bookTitle":"Rework"},{"id":"maplin","name":"Maplin","title":"The electronics help desk closes","year":"2018","category":"BUSINESS","emoji":"🔌","loss":"Administration in 2018","story":"Maplin served hobbyists and fixers who needed a cable, a component and someone who understood the question. Its stores were part workshop, part treasure hunt. Online prices undercut the shelves while the product range widened into general gadgets. Footfall and margins fell together, and Maplin entered administration in 2018.","mistake":"Competing with the internet on stock while forgetting the advice was the moat.","lesson":"If expertise is the difference, make expertise the offer, not a free extra beside cheaper boxes.","book":"rework","bookTitle":"Rework"},{"id":"comet-group","name":"Comet Group","title":"Plugged out by thin margins","year":"2012","category":"BUSINESS","emoji":"📺","loss":"Administration in 2012","story":"Comet sold televisions, appliances and computers through big British sheds. Extended warranties and scale were meant to protect a business where the products themselves kept getting cheaper. Consumer electronics became a showroom for online baskets. Comet changed owners for a token sum, still could not fix cash and credit insurance, and collapsed into administration in 2012.","mistake":"Relying on add ons to rescue a core offer customers could price in seconds.","lesson":"Transparent prices punish any model that needs confusion to make margin.","book":"profit-first","bookTitle":"Profit First"},{"id":"mothercare-uk","name":"Mothercare UK","title":"The baby shop shrinks home","year":"2019","category":"BUSINESS","emoji":"👶","loss":"UK arm in administration in 2019","story":"Mothercare was the trusted British name for pregnancy, prams and first clothes. Parents bought reassurance as much as products. Supermarkets, Amazon and specialist online rivals squeezed the UK stores while rents stayed high. The UK business entered administration in 2019, closing stores even though the brand continued through international and later arrangements.","mistake":"Selling trust while letting convenience move elsewhere.","lesson":"Trust slows decline. It does not stop customers choosing the easier basket.","book":"innovators-dilemma","bookTitle":"The Innovator's Dilemma"},{"id":"laura-ashley","name":"Laura Ashley","title":"Floral prints meet empty shops","year":"2020","category":"BUSINESS","emoji":"🌸","loss":"Administration in 2020","story":"Laura Ashley turned floral romantic style into fashion and home furnishing across Britain. The brand made a mood recognisable from a doorway. The mood aged faster than the model refreshed it. Store costs, changing taste and then the pandemic retail shutdown pushed the business into administration in 2020, though the brand name survived under new ownership.","mistake":"Letting a strong aesthetic become a period costume.","lesson":"Style brands must keep reinterpreting the codes that made them famous, or the codes become a museum label.","book":"innovators-dilemma","bookTitle":"The Innovator's Dilemma"},{"id":"linens-n-things","name":"Linens 'n Things","title":"The housing crash enters the bedroom","year":"2008","category":"BUSINESS","emoji":"🛏️","loss":"Liquidated in 2008","story":"Linens 'n Things sold the finishing touches of American homes and grew beside Bed Bath and Beyond. A private equity buyout loaded the chain with debt just before homes stopped feeling richer. The housing crash cut demand for exactly the discretionary home goods it sold. Debt left no room to wait, suppliers tightened, and the chain liquidated in 2008.","mistake":"Buying a cyclical retailer as if the cycle had retired.","lesson":"Leverage turns a bad season into a death sentence because time becomes the creditor's property.","book":"psychology-of-money","bookTitle":"The Psychology of Money"},{"id":"sharper-image","name":"Sharper Image","title":"Gadgets without gravity","year":"2008","category":"BUSINESS","emoji":"🛒","loss":"Bankrupt in 2008","story":"The Sharper Image made mall shopping feel like a glimpse of tomorrow: massage chairs, air purifiers and expensive curiosities. Catalogues turned novelty into desire. Its best known air purifier became a legal and reputational problem, novelty proved easy to copy, and the recession hit discretionary gadgets. The company filed for bankruptcy in 2008 and closed its stores.","mistake":"Building a premium novelty store on products that could not stay novel or necessary.","lesson":"Wonder has a short shelf life. A store built on it must reinvent the wonder faster than rent comes due.","book":"rework","bookTitle":"Rework"},{"id":"brookstone","name":"Brookstone","title":"The airport chair loses the mall","year":"2018","category":"BUSINESS","emoji":"💺","loss":"Bankrupt in 2018","story":"Brookstone sold playful problem solvers and chairs people tested while killing time. It thrived when malls were entertainment and a gadget could be discovered by wandering. Ecommerce took the wandering, malls lost traffic, and much of the range could be found cheaper or better reviewed online. Brookstone filed again in 2018 and closed mall stores, keeping a smaller airport and online life.","mistake":"Depending on footfall to create desire for products search could explain faster.","lesson":"Discovery retail dies when discovery becomes a search box.","book":"innovators-dilemma","bookTitle":"The Innovator's Dilemma"},{"id":"stein-mart","name":"Stein Mart","title":"Off price meets a closed world","year":"2020","category":"BUSINESS","emoji":"👗","loss":"Bankrupt in 2020","story":"Stein Mart promised department store brands at discount prices to loyal middle market shoppers. It survived cycles by serving customers who liked the hunt without luxury theatre. Online off price rivals grew, stores aged, and the pandemic removed the in person hunt at the worst moment. Stein Mart filed for bankruptcy in 2020 and liquidated its stores.","mistake":"Serving loyal shoppers while the channel moved under them.","lesson":"Loyalty delays change. It rarely cancels it.","book":"mighty-fall","bookTitle":"How the Mighty Fall"},{"id":"lord-and-taylor","name":"Lord and Taylor","title":"America's oldest store closes","year":"2020","category":"HISTORY","emoji":"🏬","loss":"Liquidation began in 2020","story":"Lord and Taylor dressed American department store history from 1826, with holiday windows and a Fifth Avenue flagship that felt civic as much as commercial. Few retail names carried more memory. Ownership churn, department store decline and a failed attempt to become a fashion startup asset left it exposed. It entered bankruptcy in 2020 and the remaining stores were liquidated.","mistake":"Treating heritage as a substitute for a customer proposition.","lesson":"A famous address can make decline look grander. It does not make it slower.","book":"mighty-fall","bookTitle":"How the Mighty Fall"},{"id":"frys-electronics","name":"Frys Electronics","title":"The themed superstore powers down","year":"2021","category":"BUSINESS","emoji":"💻","loss":"Closed overnight in 2021","story":"Fry's built cavernous themed electronics stores where enthusiasts could buy a resistor, a server and a snack in one trip. In Silicon Valley it felt like a hardware cathedral. Vendor terms shifted to consignment, shelves emptied, and online buying removed the pilgrimage. Fry's closed all stores overnight in 2021, ending a ritual many builders assumed would always exist.","mistake":"Letting empty shelves tell customers the ending before management admitted it.","lesson":"Retail trust is visible. When the shelf looks abandoned, the brand has already spoken.","book":"profit-first","bookTitle":"Profit First"},{"id":"sports-authority","name":"Sports Authority","title":"Outrun by the internet and debt","year":"2016","category":"BUSINESS","emoji":"🏀","loss":"Liquidated in 2016","story":"Sports Authority put huge sporting goods stores across America, selling the idea that every season and school team began under one roof. It had scale, brands and local presence. Debt, Dick's Sporting Goods, Amazon and brand direct sales compressed it from all sides. The company filed in 2016 expecting to save part of the chain, then liquidated when buyers valued pieces more than the whole.","mistake":"Carrying big boxes while demand learned to arrive by parcel and recommendation.","lesson":"Scale helps only when it lowers cost faster than it raises rent.","book":"good-to-great","bookTitle":"Good to Great"},{"id":"kb-toys","name":"KB Toys","title":"The mall toy store runs out of quarters","year":"2008","category":"BUSINESS","emoji":"🧸","loss":"Liquidated after 2008 bankruptcy","story":"KB Toys lived in malls and sold impulse joy near food courts. It survived the first rise of big box toy aisles by being close, bright and convenient. Walmart, Target and Toys R Us squeezed price while malls weakened. A leveraged structure left little room, and after a second bankruptcy KB liquidated in the 2008 holiday season.","mistake":"Renting convenience in locations whose traffic was no longer guaranteed.","lesson":"Location is a strategy only while the crowd still comes to that location.","book":"profit-first","bookTitle":"Profit First"},{"id":"charlotte-russe","name":"Charlotte Russe","title":"Fast fashion loses its mall","year":"2019","category":"BUSINESS","emoji":"👚","loss":"Stores liquidated in 2019","story":"Charlotte Russe sold young women's fashion at mall prices and speed. It depended on teenagers treating the mall as social media with changing rooms. Social media moved to phones, rivals shipped faster online, and teen mall traffic thinned. The chain filed in 2019 and liquidated stores, though the brand later reappeared in altered form.","mistake":"Confusing the place young people gathered with the reason they gathered.","lesson":"Follow the customer, not the building the customer used to visit.","book":"innovators-dilemma","bookTitle":"The Innovator's Dilemma"},{"id":"the-limited","name":"The Limited","title":"The store becomes a website, then a memory","year":"2017","category":"BUSINESS","emoji":"👗","loss":"All stores closed in 2017","story":"The Limited helped invent modern American mall fashion and launched or nurtured brands that defined shopping for a generation. Its name once meant taste at scale. The parent empire moved on, malls weakened, and the chain lost a clear reason to exist beside faster rivals. In 2017 it closed all remaining stores and briefly pointed shoppers online before the brand faded.","mistake":"Keeping a famous name after the operating magic had left the building.","lesson":"Names keep value only when the experience keeps proving them.","book":"good-strategy-bad-strategy","bookTitle":"Good Strategy Bad Strategy"},{"id":"american-apparel","name":"American Apparel","title":"The provocateur files twice","year":"2016","category":"BUSINESS","emoji":"👕","loss":"Brand sold after bankruptcy","story":"American Apparel sold basics with sweatshop free ethics, bold ads and a founder whose behaviour became inseparable from the brand. The mix created devotion and chaos in equal measure. Board fights, misconduct allegations, debt and inventory problems turned provocation into instability. After bankruptcies, the brand was sold to Gildan in 2016 and the original company story ended.","mistake":"Letting founder theatre become the operating system.","lesson":"A brand can borrow the founder's voltage, but governance decides whether it powers the lights or burns the house.","book":"hard-things","bookTitle":"The Hard Thing About Hard Things"},{"id":"gymboree","name":"Gymboree","title":"Kids grow, debt does not shrink","year":"2019","category":"BUSINESS","emoji":"🧒","loss":"Liquidated in 2019","story":"Gymboree dressed American childhood in bright colours and mall convenience. Parents returned because sizes changed as fast as children did. A leveraged buyout, weaker malls and competition from Target, Amazon and resale squeezed the model. A second bankruptcy in 2019 led to liquidation of Gymboree and Crazy 8 stores.","mistake":"Assuming repeat need would protect a store network built on expensive locations.","lesson":"Need is not loyalty when the same need is met cheaper during the same school run.","book":"psychology-of-money","bookTitle":"The Psychology of Money"},{"id":"barneys-new-york","name":"Barneys New York","title":"Luxury loses its landlord math","year":"2019","category":"BUSINESS","emoji":"🛍️","loss":"Bankrupt in 2019","story":"Barneys made luxury feel witty and downtown, with windows and buyers that influenced fashion far beyond its size. The Madison Avenue flagship was a cultural signal. Rent escalation, luxury moving online and to brand boutiques, plus debt, destroyed the arithmetic. Barneys filed in 2019, sold its brand and closed the flagship that had made it famous.","mistake":"Letting a rent reset decide whether a cultural institution lives.","lesson":"Prestige is not margin. A landlord can collect the difference.","book":"good-strategy-bad-strategy","bookTitle":"Good Strategy Bad Strategy"},{"id":"northern-rock","name":"Northern Rock","title":"The run everyone could see","year":"2007","category":"MONEY","emoji":"🏦","loss":"Nationalised in 2008","story":"Northern Rock grew fast by borrowing in wholesale markets to fund mortgages, becoming a British success story of aggressive expansion. Its model worked while markets stayed calm and open. When credit markets froze in 2007, savers queued outside branches in the first visible British bank run for generations. Emergency support failed to restore confidence and the bank was nationalised in 2008.","mistake":"Funding long promises with short confidence.","lesson":"If your business needs calm every day, panic is not an accident. It is a design flaw revealing itself.","book":"black-swan","bookTitle":"The Black Swan"},{"id":"bradford-and-bingley","name":"Bradford and Bingley","title":"Buy to let meets the bailout","year":"2008","category":"MONEY","emoji":"🏠","loss":"Nationalised in 2008","story":"Bradford and Bingley specialised in buy to let and self certified mortgages, riding Britain's property faith. A former building society became a symbol of how far mortgage lending had travelled from caution. Property prices turned, funding dried up and regulators lost faith. In 2008 the government nationalised the bank and sold branches and savings to Santander, leaving the loan book to be wound down.","mistake":"Concentrating in the asset everyone believed could not fall nationally.","lesson":"A niche lender is a leveraged opinion about one market. When the opinion breaks, the bank is the opinion.","book":"psychology-of-money","bookTitle":"The Psychology of Money"},{"id":"countrywide-financial","name":"Countrywide Financial","title":"The mortgage machine is sold in distress","year":"2008","category":"MONEY","emoji":"🏡","loss":"Sold to Bank of America in 2008","story":"Countrywide became America's largest mortgage lender by making home loans feel easy in a rising market. Its sales engine and political influence made it central to the housing boom. The loans soured, investigations grew and funding markets panicked. Bank of America bought Countrywide in 2008 in what looked like rescue and became years of legal and mortgage costs.","mistake":"Optimising for origination volume while someone else was meant to hold the risk.","lesson":"If you are paid for making the loan and not for whether it survives, volume will eventually invent danger.","book":"principles-dalio","bookTitle":"Principles"},{"id":"indymac","name":"IndyMac","title":"The televised bank run","year":"2008","category":"MONEY","emoji":"🏦","loss":"Seized by regulators in 2008","story":"IndyMac grew from Countrywide roots into a major mortgage bank focused on Alt A loans. It looked modern and specialised while housing credit kept expanding. A senator's public letter about its health helped trigger withdrawals, and regulators seized IndyMac in 2008 in one of the largest US bank failures then seen. The mortgage quality underneath made rescue hard to imagine.","mistake":"Holding shaky assets while confidence became the only liquid thing left.","lesson":"Banks die from doubt before arithmetic finishes them. Trust is the real capital buffer.","book":"black-swan","bookTitle":"The Black Swan"},{"id":"wachovia","name":"Wachovia","title":"Too weak to stand, too big to drop","year":"2008","category":"MONEY","emoji":"🏦","loss":"Forced into Wells Fargo sale","story":"Wachovia was a proud American banking name built through mergers into a coast to coast giant. Its purchase of Golden West added a portfolio of option adjustable rate mortgages at the peak. Those mortgages and the wider panic crushed confidence in 2008. Regulators pushed a rescue, Citigroup circled, and Wells Fargo ultimately acquired Wachovia without government assistance in a weekend that showed how close it stood to failure.","mistake":"Buying growth in the most dangerous loan book at the top of the cycle.","lesson":"An acquisition can import the exact weather that sinks the ship.","book":"psychology-of-money","bookTitle":"The Psychology of Money"},{"id":"new-century-financial","name":"New Century Financial","title":"The first domino with a logo","year":"2007","category":"MONEY","emoji":"📉","loss":"Bankrupt in 2007","story":"New Century was a star of subprime lending, making loans to borrowers traditional banks avoided and selling the risk into roaring markets. Profits made the model look like financial inclusion plus genius. Early payment defaults forced it to buy back bad loans just as warehouse lenders pulled funding. New Century filed for bankruptcy in April 2007, an early public warning that the housing machine was reversing.","mistake":"Selling risk so fast that buyback clauses became invisible.","lesson":"If the exit door locks when quality falls, you never sold the risk. You rented confidence.","book":"psychology-of-money","bookTitle":"The Psychology of Money"},{"id":"drexel-burnham-lambert","name":"Drexel Burnham Lambert","title":"Junk bond ashes","year":"1990","category":"MONEY","emoji":"🔥","loss":"Bankrupt in 1990","story":"Drexel and Michael Milken turned high yield bonds into fuel for corporate raiders and outsider companies. For a decade the firm made Wall Street's old hierarchy look slow. Insider trading investigations, a guilty plea by Milken, regulatory pressure and a junk market collapse destroyed trust and liquidity. Drexel filed for bankruptcy in 1990, proving how fast a market maker can become a museum.","mistake":"Building a market on access, confidence and rules that could not survive daylight.","lesson":"Financial innovation that needs secrecy from regulators is usually borrowing time.","book":"principles-dalio","bookTitle":"Principles"},{"id":"continental-illinois","name":"Continental Illinois","title":"Too big to fail learns its name","year":"1984","category":"MONEY","emoji":"🏛️","loss":"Rescued and effectively nationalised in 1984","story":"Continental Illinois was a major American bank that lent heavily into energy and bought troubled loans from Penn Square. It looked like scale and sophistication from Chicago. Bad energy loans and a modern electronic bank run forced an FDIC rescue in 1984 so large it popularised the idea of too big to fail. Shareholders and management were swept aside while the bank survived under control.","mistake":"Mistaking size for safety while asset quality rotted.","lesson":"A rescue can save the system and still bury the institution that needed it.","book":"black-swan","bookTitle":"The Black Swan"},{"id":"republic-first-bank","name":"Republic First Bank","title":"The smaller echo of 2023","year":"2024","category":"MONEY","emoji":"🏦","loss":"Seized in 2024","story":"Republic First Bank in Philadelphia shared a confusingly similar name with the much larger First Republic but lived a quieter regional life. It struggled with costs, governance fights and the post 2023 deposit climate. Regulators closed Republic First in April 2024 and sold most deposits and assets to Fulton Bank. It became the first US bank failure of 2024 and a reminder that confidence problems did not end with the famous names.","mistake":"Letting governance noise meet a nervous deposit era.","lesson":"Small banks do not need a national panic to fail. They need doubt plus delay.","book":"psychology-of-money","bookTitle":"The Psychology of Money"},{"id":"lernout-and-hauspie","name":"Lernout and Hauspie","title":"The voice was ventriloquism","year":"2001","category":"FRAUD","emoji":"🗣️","loss":"Bankrupt after accounting scandal","story":"Lernout and Hauspie sold speech recognition when voice interfaces still felt like magic. Belgium celebrated it as a technology champion and investors treated language software as a national future. Revenue in Korea was largely fabricated and accounting unravelled under scrutiny. The company filed for bankruptcy in 2001, dragging reputations and a national tech dream with it.","mistake":"Letting reported growth in distant units escape verification because the story needed heroes.","lesson":"The harder a market is to audit, the more boring your controls must be.","book":"bad-blood","bookTitle":"Bad Blood"},{"id":"exodus-communications","name":"Exodus Communications","title":"Hosting the bubble at full price","year":"2001","category":"BUSINESS","emoji":"🌐","loss":"Bankrupt in 2001","story":"Exodus ran premium web hosting data centres for dotcoms that believed traffic would become money soon enough. It bought rivals and built capacity as if the internet's first boom was a floor, not a wave. Customers vanished, debt remained and data centre economics turned brutal. Exodus filed for bankruptcy in 2001 and sold assets to Cable and Wireless at a fraction of the dream.","mistake":"Selling shovels priced for a gold rush that ended before the mines opened.","lesson":"Infrastructure for hype inherits the hype cycle with interest.","book":"black-swan","bookTitle":"The Black Swan"},{"id":"psinet","name":"PSINet","title":"The internet backbone bends","year":"2002","category":"BUSINESS","emoji":"🌐","loss":"Bankrupt in 2002","story":"PSINet helped commercialise the internet and expanded globally by buying providers across continents. It wanted to be the carrier behind the new economy everywhere at once. The debt used to buy growth met falling prices and the telecom crash. PSINet filed for bankruptcy in 2002 and sold its pieces, another backbone bent by the cost of becoming global too fast.","mistake":"Buying geography before proving density economics.","lesson":"Coverage is not advantage if every new country brings more cost than pricing power.","book":"good-to-great","bookTitle":"Good to Great"},{"id":"value-america","name":"Value America","title":"Tomorrow's store, yesterday's cash","year":"2000","category":"STARTUP","emoji":"🛒","loss":"Bankrupt in 2000","story":"Value America promised an online superstore without inventory, connecting brands directly to shoppers. Founder Tom Via promotion and a huge IPO made it a symbol of internet retail ambition. The model confused orders, fulfilment broke down, returns and costs mounted, and confidence collapsed after restated expectations. It filed for bankruptcy in 2000, less than a year after peak hype.","mistake":"Removing inventory while keeping all the hard parts of retail.","lesson":"Asset light is not problem light. Fulfilment still votes.","book":"lean-startup","bookTitle":"The Lean Startup"},{"id":"garden-com","name":"Garden.com","title":"Planted at the peak","year":"2000","category":"STARTUP","emoji":"🌱","loss":"Shut in 2000","story":"Garden.com sold plants and gardening advice online with editorial charm and real enthusiasm from home gardeners. It raised public money while ecommerce still felt like a land grab. Shipping live plants is hard, seasons are unforgiving and customer acquisition ate the margin. The company shut in 2000 after failing to secure more funding, a gentle brand inside a violent market lesson.","mistake":"Ignoring that some categories fight physics, weather and seasonality every day.","lesson":"Nature is a supply chain partner that does not care about your burn multiple.","book":"e-myth","bookTitle":"The E-Myth Revisited"},{"id":"alladvantage","name":"AllAdvantage","title":"Paying people to pretend","year":"2001","category":"STARTUP","emoji":"💻","loss":"Closed in 2001","story":"AllAdvantage paid users to browse with an ad bar and rewarded referrals, turning attention into a multilevel money fountain. It grew explosively because joining felt like being paid by the internet itself. Advertisers would not fund the behaviour at the promised rate, and much of the attention was low quality or gamed. When ad markets fell, AllAdvantage shut in 2001.","mistake":"Paying for the metric advertisers wished they were buying.","lesson":"If users come for the payout, the product is the payout. When it shrinks, so does the crowd.","book":"mom-test","bookTitle":"The Mom Test"},{"id":"joost","name":"Joost","title":"Television from the future, blocked by rights","year":"2009","category":"STARTUP","emoji":"📺","loss":"Sold after failing to scale","story":"Joost came from the founders of Skype and Kazaa and promised legal internet television through peer to peer distribution. The pedigree made broadcasters and investors listen. Content deals were limited, browser video improved, and Hulu and YouTube made installation feel old. Joost sold assets in 2009 after layoffs, a brilliant delivery system searching for a catalogue.","mistake":"Solving distribution before securing the thing people wanted to watch.","lesson":"Pipes do not create demand when the water belongs to someone else.","book":"crossing-chasm","bookTitle":"Crossing the Chasm"},{"id":"bebo","name":"Bebo","title":"Sold for a fortune, rebought for a song","year":"2013","category":"STARTUP","emoji":"💬","loss":"Original company bankrupt in 2013","story":"Bebo was huge with young users in Britain, Ireland and New Zealand before Facebook became unavoidable. AOL bought it for 850 million dollars as a social future. AOL never gave it a winning role and sold it for a tiny fraction. Later owners tried revivals, but the original company behind the relaunch entered bankruptcy in 2013, a social network reduced to a cautionary price chart.","mistake":"Being bought as a strategy by an owner without one.","lesson":"Acquisition is not an ending. It is a new manager for the same problem.","book":"hard-things","bookTitle":"The Hard Thing About Hard Things"},{"id":"xanga","name":"Xanga","title":"The diary moved out","year":"2013","category":"BUSINESS","emoji":"🌐","loss":"Team tried to sell and relaunch in 2013","story":"Xanga hosted online diaries for a generation that learned identity in public posts and customised pages. It was intimate where later feeds became performative. Facebook, Tumblr and phones changed the diary into the feed. Xanga attempted a paid relaunch and sale in 2013 but never regained cultural gravity, fading from host to archive of adolescent internet memory.","mistake":"Assuming a format people loved would survive the device and feed changing around it.","lesson":"Communities do not only churn. Their rituals can become obsolete.","book":"innovators-dilemma","bookTitle":"The Innovator's Dilemma"},{"id":"air-berlin","name":"Air Berlin","title":"The second airline runs out of patrons","year":"2017","category":"BUSINESS","emoji":"✈️","loss":"Insolvent in 2017","story":"Air Berlin grew into Germany's second airline through acquisitions and a hybrid promise between holiday and business travel. Abu Dhabi Etihad's money kept the ambition airborne. Losses persisted, strategy blurred and Etihad stopped funding after its own expansion bets soured. Air Berlin filed for insolvency in 2017 and its final flight became a national farewell.","mistake":"Depending on one shareholder's patience to fund a model that never stood alone.","lesson":"A patron can delay the reckoning. Only a working route network can cancel it.","book":"hard-things","bookTitle":"The Hard Thing About Hard Things"},{"id":"wow-air","name":"WOW air","title":"Purple planes, red ink","year":"2019","category":"BUSINESS","emoji":"🛫","loss":"Ceased operations in 2019","story":"WOW air made Iceland a cheap bridge between Europe and North America with purple planes and playful fares. Travellers loved the prices and Reykjavik became a stopover adventure. Rapid expansion, leased aircraft, fuel costs and debt outran the fare model. Rescue talks failed and WOW ceased operations abruptly in 2019, stranding passengers and puncturing Iceland's tourism boom.","mistake":"Pricing for applause while leasing for permanence.","lesson":"Low fares are a promise. Aircraft leases are a bill. The bill speaks longer.","book":"profit-first","bookTitle":"Profit First"},{"id":"flybe","name":"Flybe","title":"Two lives, same storm","year":"2023","category":"BUSINESS","emoji":"🛩️","loss":"Collapsed again in 2023","story":"Flybe connected British regions that trains and larger airlines neglected. It was easy to criticise and hard to replace, which kept rescuers interested. The first Flybe collapsed in 2020. A revived version launched in 2022 into high costs, weak demand and operational delays, then collapsed again in 2023. The map still needed the routes more than the model could fund them.","mistake":"Believing a necessary service must therefore be a viable business.","lesson":"Social value can justify subsidy. It does not create margin by itself.","book":"profit-first","bookTitle":"Profit First"},{"id":"alitalia","name":"Alitalia","title":"The flag carrier is replaced","year":"2021","category":"HISTORY","emoji":"✈️","loss":"Replaced by ITA in 2021","story":"Alitalia carried Italian design, politics and pride around the world for seven decades. Successive governments treated the flag carrier as too symbolic to let fall. Losses, strikes, ownership drama and state aid kept it alive without making it healthy. Italy finally replaced Alitalia with ITA Airways in 2021, ending the name while admitting the old company could not be saved as it was.","mistake":"Letting national symbolism fund commercial denial.","lesson":"A flag can attract rescue. It cannot fix load factors, labour cost or fleet choices.","book":"mighty-fall","bookTitle":"How the Mighty Fall"},{"id":"air-namibia","name":"Air Namibia","title":"The desert airline is grounded","year":"2021","category":"BUSINESS","emoji":"✈️","loss":"Liquidated in 2021","story":"Air Namibia connected a vast, sparse country to the world and carried national pride far beyond its passenger numbers. Governments kept funding the flag because the map argued for it. Debt, aircraft leases and the pandemic pushed the state to stop paying. The airline was liquidated in 2021, leaving routes, staff and a national symbol to be argued over in court and parliament.","mistake":"Treating a public service as an airline and an airline as a public service without funding either honestly.","lesson":"If the mission is national connection, price it as policy. If it is a business, run it as one.","book":"profit-first","bookTitle":"Profit First"},{"id":"comair-south-africa","name":"Comair South Africa","title":"The franchise loses the sky","year":"2022","category":"BUSINESS","emoji":"✈️","loss":"Liquidation in 2022","story":"Comair operated British Airways branded flights and kulula.com in South Africa, surviving decades of aviation shocks. It entered business rescue during the pandemic hoping to return smaller and stronger. A funding plan failed after aircraft groundings and creditor pressure. Comair was liquidated in 2022, ending an unusually long run for an African airline group.","mistake":"Assuming rescue time would be granted because history was long.","lesson":"In aviation, history does not pay for fuel while negotiators talk.","book":"hard-things","bookTitle":"The Hard Thing About Hard Things"},{"id":"paramount-airways","name":"Paramount Airways","title":"Luxury regional, grounded early","year":"2010","category":"BUSINESS","emoji":"✈️","loss":"Ceased operations in 2010","story":"Paramount Airways tried to make Indian regional flying feel premium from Chennai, with all business seating and routes larger airlines under-served. It stood out in a market obsessed with low fares. Aircraft leasing disputes, regulatory trouble and cash pressure grounded the model. Operations ceased in 2010 and the licence fight became the story, not the service.","mistake":"Building a premium difference in a market where price and permission were the real gates.","lesson":"Regulation and aircraft access are not back office details in aviation. They are the runway.","book":"principles-dalio","bookTitle":"Principles"},{"id":"air-costa","name":"Air Costa","title":"Regional wings, national costs","year":"2017","category":"BUSINESS","emoji":"✈️","loss":"Stopped flying in 2017","story":"Air Costa launched from Vijayawada to connect Indian cities that felt ignored by big networks. Regional pride and Embraer jets gave it a clear opening story. Leasing costs, low yields and expansion pressure met the thin economics of regional Indian aviation. Flights stopped in 2017 amid unpaid dues and attempts to find investors failed.","mistake":"Confusing underserved routes with profitable routes.","lesson":"A route can be needed and still lose money on every seat that says thank you.","book":"crossing-chasm","bookTitle":"Crossing the Chasm"},{"id":"trujet","name":"TruJet","title":"The regional promise stalls","year":"2022","category":"BUSINESS","emoji":"✈️","loss":"Operations halted by 2022","story":"TruJet built an Indian regional network under the UDAN push for smaller city connectivity, at one point serving routes the big airlines ignored. Subsidy and scarcity made expansion look plausible. Fleet problems, funding stress and the pandemic broke continuity. Operations stopped and revival attempts faded by 2022, another regional carrier learning that small routes can carry large fixed costs.","mistake":"Expanding a thin margin network before the balance sheet could survive interruptions.","lesson":"In aviation, one grounded plane can be a strategy event.","book":"hard-things","bookTitle":"The Hard Thing About Hard Things"},{"id":"uninor-india","name":"Uninor India","title":"The licence earthquake","year":"2013","category":"BUSINESS","emoji":"📶","loss":"Original brand wound down after licence loss","story":"Uninor brought Telenor's low cost discipline to India's mobile price war and won millions of subscribers quickly. It looked built for exactly the market it entered. The Supreme Court cancelled 122 telecom licences in the 2G scandal in 2012, including Uninor's path in several circles. Telenor fought, restructured and later exited India, but the original Uninor ambition died in the legal rubble.","mistake":"Treating licence risk as paperwork in a sector where permission is the asset.","lesson":"When the state grants your right to operate, legal diligence is product strategy.","book":"principles-dalio","bookTitle":"Principles"},{"id":"jabong","name":"Jabong","title":"Folded into the sister closet","year":"2020","category":"BUSINESS","emoji":"👟","loss":"Closed and folded into Myntra in 2020","story":"Jabong helped teach India to buy fashion online, with brands, sales events and a young urban customer. Flipkart acquired it after buying Myntra, giving one parent two fashion doors. Running both doors cost more than the extra reach earned. Flipkart shut Jabong in 2020 and pushed users to Myntra, accepting focus over a famous second label.","mistake":"Owning two answers to the same customer and paying twice for the question.","lesson":"Portfolio logic beats sibling rivalry when acquisition costs rise.","book":"good-strategy-bad-strategy","bookTitle":"Good Strategy Bad Strategy"},{"id":"peppertap","name":"PepperTap","title":"Groceries before the economics ripened","year":"2016","category":"STARTUP","emoji":"🥬","loss":"Delivery shut in 2016","story":"PepperTap brought hyperlocal grocery delivery to Indian cities before dark stores and quick commerce discipline existed. It raised money and expanded while customers still needed convincing. Orders were expensive to assemble from partner stores, discounts trained low loyalty and logistics ate the basket. PepperTap shut consumer delivery in 2016 and tried to pivot away from the fire.","mistake":"Scaling a service whose every order taught it to lose money more efficiently.","lesson":"Convenience is not a model until the basket pays for the trip.","book":"lean-startup","bookTitle":"The Lean Startup"},{"id":"askme","name":"AskMe","title":"Local search, national burn","year":"2016","category":"STARTUP","emoji":"❓","loss":"Shut in 2016","story":"AskMe tried to combine Indian local search, deals, classifieds and commerce into one consumer internet bazaar. Celebrity ads and acquisitions made it look like a group being assembled at speed. The pieces never became one habit strong enough to fund the spend. A major investor dispute and cash crunch shut operations in 2016, leaving vendors and employees chasing dues.","mistake":"Buying adjacent features instead of deepening one repeated behaviour.","lesson":"A bundle is not synergy if each part needs its own reason to return.","book":"good-strategy-bad-strategy","bookTitle":"Good Strategy Bad Strategy"},{"id":"koovs","name":"Koovs","title":"The ASOS of India runs out of runway","year":"2019","category":"BUSINESS","emoji":"👗","loss":"Administration in 2019","story":"Koovs sold Western fashion to Indian shoppers with London design language and celebrity gloss. It listed in London and tried to build an India focused fashion brand across two worlds. Cash kept running short and a promised investment linked to Future Group unravelled amid that group's own stress. Koovs entered administration in 2019 after funding failed to land in time.","mistake":"Making survival depend on one rescue cheque from a stressed partner.","lesson":"Counterparty risk is still risk, even when the cheque has a famous signature.","book":"psychology-of-money","bookTitle":"The Psychology of Money"},{"id":"wooplr","name":"Wooplr","title":"Discovery without a till","year":"2019","category":"STARTUP","emoji":"🛍️","loss":"Shut in 2019","story":"Wooplr helped Indian shoppers discover fashion from boutiques and social posts before Instagram shopping felt normal. The Bengaluru team tried discovery, commerce and later business tools. Attention did not convert into enough transactions, and platforms absorbed social shopping into their own feeds. Wooplr shut in 2019 after pivots could not find a paying centre.","mistake":"Building discovery while platforms owned both audience and checkout.","lesson":"If someone else controls the moment of purchase, your insight becomes their feature.","book":"crossing-chasm","bookTitle":"Crossing the Chasm"},{"id":"trell","name":"Trell","title":"The pivot that kept moving","year":"2023","category":"STARTUP","emoji":"🎬","loss":"Shut after decline","story":"Trell began as Indian language discovery and rode short video and social commerce waves after TikTok left India. It raised large rounds while trying to become a lifestyle commerce destination. Commerce did not mature fast enough, costs stayed high and governance questions hurt trust during a funding winter. After layoffs and shrinkage, Trell wound down by 2023.","mistake":"Chasing each new format before the previous one paid for itself.","lesson":"A pivot should narrow the bet. Trell kept widening the casino.","book":"lean-startup","bookTitle":"The Lean Startup"},{"id":"frontrow","name":"FrontRow","title":"Celebrity classes meet a quiet room","year":"2023","category":"STARTUP","emoji":"🎸","loss":"Shut in 2023","story":"FrontRow sold learning from famous Indian names in music, comedy, sport and film. During lockdown, aspiration plus celebrity looked like a new education shelf. Post pandemic demand fell, courses were hard to repeat and celebrity attention was expensive. FrontRow cut deeply and shut in 2023, returning some capital rather than pretending the class was still full.","mistake":"Mistaking lockdown curiosity for a durable learning habit.","lesson":"Star teachers can open a course. Only outcomes and community make students return.","book":"mom-test","bookTitle":"The Mom Test"},{"id":"lido-learning","name":"Lido Learning","title":"The class ends mid term","year":"2022","category":"STARTUP","emoji":"📚","loss":"Operations shut in 2022","story":"Lido Learning sold small group online classes to Indian parents who wanted school support with more attention. It grew during the edtech boom and promised quality over noisy large batches. High teacher and acquisition costs met falling demand as schools reopened. In 2022 classes stopped abruptly and parents sought refunds, showing how fragile trust becomes when prepaid education meets weak cash.","mistake":"Selling long promises while funding operations month to month.","lesson":"Prepaid revenue is a liability to teach, not a trophy to spend.","book":"profit-first","bookTitle":"Profit First"},{"id":"whitehat-jr","name":"WhiteHat Jr","title":"The white hat becomes a warning","year":"2023","category":"BUSINESS","emoji":"👦","loss":"Brand shut by Byju's in 2023","story":"WhiteHat Jr sold coding classes for children with aggressive promises about future jobs and fame. Byju's bought it for about 300 million dollars during the pandemic education rush. Parents and critics pushed back on sales tactics and claims, while the economics of one to one classes stayed hard. Byju's shut the brand in 2023 as its own crisis swallowed the empire that had bought it.","mistake":"Using parental anxiety as fuel and calling it aspiration.","lesson":"Fear can convert a trial. It corrodes the trust a children's brand needs to survive.","book":"bad-blood","bookTitle":"Bad Blood"},{"id":"munchery","name":"Munchery","title":"Restaurant quality, factory pain","year":"2019","category":"STARTUP","emoji":"🍱","loss":"Shut in 2019","story":"Munchery delivered chef designed meals that felt like a good restaurant had learned logistics. Investors liked the idea of owning dinner without dining rooms. Prepared food at scale brought waste, labour, delivery and quality control into one expensive knot. After raising large sums and cutting markets, Munchery shut abruptly in 2019 owing vendors and goodwill.","mistake":"Trying to be kitchen, courier and restaurant brand before any one layer worked.","lesson":"Vertical integration multiplies problems before it multiplies margin.","book":"e-myth","bookTitle":"The E-Myth Revisited"},{"id":"plated","name":"Plated","title":"The meal kit gets shelved","year":"2019","category":"STARTUP","emoji":"🍳","loss":"Shut by Albertsons in 2019","story":"Plated was a polished meal kit pioneer that reached television fame and sold to Albertsons, which planned to put kits into grocery aisles. The acquisition looked like distribution solving customer acquisition. Meal kits remained costly to ship and easy to cancel. Albertsons shut Plated's subscription service in 2019 while keeping lessons for store brands, proof that shelf space could not rescue churn.","mistake":"Believing distribution fixes a product people keep quitting.","lesson":"A new channel cannot cure a habit that leaks.","book":"lean-startup","bookTitle":"The Lean Startup"},{"id":"freshly","name":"Freshly","title":"Prepared meals lose their freshness","year":"2023","category":"STARTUP","emoji":"🥗","loss":"Shut in 2023","story":"Freshly delivered ready meals for people who wanted dinner solved without cooking. Nestlé bought full control during the pandemic when prepared convenience looked like the future. Demand normalised, prepared meal economics stayed heavy and Nestlé reassessed the portfolio. Freshly stopped operations in 2023, another pandemic winner meeting the old cost of cold food in boxes.","mistake":"Extrapolating emergency behaviour into permanent demand.","lesson":"Crisis growth must be refinanced by normal habits before the emergency ends.","book":"black-swan","bookTitle":"The Black Swan"},{"id":"juno","name":"Juno","title":"The kind ridehail meets hard streets","year":"2019","category":"STARTUP","emoji":"🚕","loss":"Shut in 2019","story":"Juno entered New York promising drivers better treatment and equity in a market angry at Uber. Riders liked the ethics and drivers liked being courted as partners. New York regulation, driver pay rules and Lyft/Uber scale made kindness expensive without enough differentiation at the curb. Parent Gett shut Juno in 2019 and focused on corporate travel.","mistake":"Assuming moral positioning could offset network liquidity.","lesson":"In marketplaces, values matter after wait time, price and reliability clear the bar.","book":"blue-ocean-strategy","bookTitle":"Blue Ocean Strategy"},{"id":"chariot","name":"Chariot","title":"The commuter van that missed the bus","year":"2019","category":"STARTUP","emoji":"🚌","loss":"Shut by Ford in 2019","story":"Chariot crowdsourced commuter van routes in cities and sold to Ford as mobility moved from cars to services. It felt like transit designed by software rather than history. Routes were hard to fill profitably, regulations varied and public transit economics are unforgiving. Ford shut Chariot in 2019 after expanding and then admitting the vans did not make a business.","mistake":"Treating transit like an app market instead of a density puzzle.","lesson":"Commuters forgive many things except a route that does not match the day twice.","book":"systems-thinking","bookTitle":"Thinking in Systems"},{"id":"bridj","name":"Bridj","title":"Pop up buses, permanent costs","year":"2017","category":"STARTUP","emoji":"🚐","loss":"Shut in 2017","story":"Bridj tried data driven pop up bus routes in Boston and Kansas City, promising transit that learned where people actually wanted to go. Cities liked the experiment because it felt cheaper than building fixed systems. The model needed subsidy, density and patience at the same time. A hoped partnership did not close, funding failed and Bridj shut in 2017.","mistake":"Needing public patience with private burn.","lesson":"If the buyer is a city, the sales cycle is part of the runway calculation.","book":"hard-things","bookTitle":"The Hard Thing About Hard Things"},{"id":"sidecar","name":"Sidecar","title":"The pioneer gets passed","year":"2015","category":"STARTUP","emoji":"🚗","loss":"Shut in 2015, assets to GM","story":"Sidecar helped invent peer to peer ride sharing and experimented with deliveries and shared rides early. It had ideas the market later rewarded in larger companies. Uber and Lyft raised more, priced harder and won driver and rider liquidity city by city. Sidecar shut service at the end of 2015 and sold assets to GM.","mistake":"Being right about the future while underfunded in the present.","lesson":"In network markets, second place can be a research department for the winner.","book":"crossing-chasm","bookTitle":"Crossing the Chasm"},{"id":"hailo","name":"Hailo","title":"The taxi app takes the wrong road","year":"2016","category":"STARTUP","emoji":"🚕","loss":"North America exit and merger","story":"Hailo made licensed taxis bookable by app when Uber still felt insurgent. London black cab drivers gave it supply and trust in its home city. Expansion into North America burned cash against ridehail economics, and the company retreated. Hailo merged into Daimler's MyTaxi in 2016, ending the independent global taxi app dream.","mistake":"Fighting a subsidised insurgent city by city with regulated supply.","lesson":"A trusted niche can survive. A global war chest contest needs a global war chest.","book":"good-strategy-bad-strategy","bookTitle":"Good Strategy Bad Strategy"},{"id":"flightcar","name":"FlightCar","title":"Rent your parked car, meet reality","year":"2016","category":"STARTUP","emoji":"🚙","loss":"Shut in 2016","story":"FlightCar let travellers rent out cars that would otherwise sit in airport parking, sharing revenue with owners. The idea made empty parked metal look like lazy inventory. Insurance, airport rules, cleaning, damage and trust made every transaction heavier than the pitch. FlightCar shut in 2016 after legal and operational friction consumed the cleverness.","mistake":"Underestimating how many promises hide inside one shared asset.","lesson":"Sharing models fail at the handoff, not the homepage.","book":"e-myth","bookTitle":"The E-Myth Revisited"},{"id":"maven","name":"Maven","title":"GM parks its sharing app","year":"2020","category":"BUSINESS","emoji":"🔑","loss":"Shut in 2020","story":"Maven was General Motors' car sharing service for city users and gig drivers, part of the era when carmakers promised mobility subscriptions instead of only metal. It had fleet access rivals envied. Utilisation and economics never justified the strategic attention once priorities changed. GM wound Maven down in 2020, keeping pieces for other programmes and leaving the standalone app in the past.","mistake":"Launching a service business inside a product giant without a protected profit logic.","lesson":"Carmakers can supply cars. Supply is not the same as demand.","book":"good-strategy-bad-strategy","bookTitle":"Good Strategy Bad Strategy"},{"id":"spoonrocket","name":"SpoonRocket","title":"Ten minute meals, ten problems","year":"2016","category":"STARTUP","emoji":"🍔","loss":"Shut in 2016","story":"SpoonRocket cooked a tiny menu in advance and promised hot meals in about ten minutes in Berkeley and San Francisco. Speed was the product and the adrenaline was real. Cooking before orders created waste, couriers cost money and a Brazil expansion through Hellofood did not save the core. SpoonRocket shut in 2016 and sold technology remnants.","mistake":"Optimising for delivery speed before order density could pay for it.","lesson":"Fast is expensive unless the map is dense. A stopwatch is not a moat.","book":"profit-first","bookTitle":"Profit First"},{"id":"farmdrop","name":"Farmdrop","title":"The farmers market meets cold storage","year":"2021","category":"STARTUP","emoji":"🥕","loss":"Administration in 2021","story":"Farmdrop tried to make British grocery shopping local and ethical online, sourcing from producers and delivering with a cleaner conscience. Customers who cared loved the intent. Grocery margins are brutal even without higher sourcing and delivery promises. Funding tightened and Farmdrop entered administration in 2021 just before Christmas, leaving producers and shoppers exposed.","mistake":"Stacking ethical sourcing, fresh logistics and home delivery on supermarket thin margins.","lesson":"Good values still need a basket that survives delivery.","book":"profit-first","bookTitle":"Profit First"},{"id":"nomiku","name":"Nomiku","title":"The home gadget boils dry","year":"2019","category":"STARTUP","emoji":"🍲","loss":"Shut in 2019","story":"Nomiku made sous vide cooking feel approachable for home cooks after a strong Kickstarter. It sold precision food nerd joy before big appliance brands crowded the counter. Hardware margins, support, Wi-Fi product issues and a disastrous manufacturing episode around a later device drained the company. Nomiku shut in 2019, leaving apps and customers to cool.","mistake":"Treating crowdfunding heat as proof the appliance business would behave.","lesson":"Hardware punishes one bad run because inventory remembers every mistake.","book":"hard-things","bookTitle":"The Hard Thing About Hard Things"},{"id":"new-age-meats","name":"New Age Meats","title":"The cultivated bite never reaches menu scale","year":"2023","category":"STARTUP","emoji":"🥩","loss":"Closed in 2023","story":"New Age Meats pursued cultivated pork and sausages that could sell taste without slaughter. It raised money while alternative protein still enjoyed generous climate and technology optimism. Costs, regulation, funding winter and the long road to commercial plants closed in. The company shut in 2023 before proving cultivated meat could be made at food prices rather than demonstration prices.","mistake":"Funding a science timeline with venture patience measured in quarters.","lesson":"Deep tech needs milestones investors can taste, literally and financially.","book":"black-swan","bookTitle":"The Black Swan"},{"id":"no-evil-foods","name":"No Evil Foods","title":"Plant based, labour divided","year":"2021","category":"STARTUP","emoji":"🌱","loss":"Shut in 2021","story":"No Evil Foods made plant based meats with punk branding and a social mission. It reached grocery shelves while pitching values as loudly as protein content. A union fight damaged the story with exactly the customers most likely to care, while production costs and retail competition stayed hard. The company ceased operations in 2021.","mistake":"Letting the public values story and internal practice become opponents.","lesson":"Mission is an operating standard, not packaging. Staff will eventually narrate the difference.","book":"bad-blood","bookTitle":"Bad Blood"},{"id":"air-italy","name":"Air Italy","title":"A relaunch with borrowed altitude","year":"2020","category":"BUSINESS","emoji":"✈️","loss":"Liquidated in 2020","story":"Air Italy rose from Meridiana with Qatar Airways backing and a plan to challenge at Milan with new aircraft and long haul ambition. The livery promised a second Italian flag. Losses, fleet complexity and shareholder tension met the first pandemic shock. Owners put Air Italy into liquidation in February 2020, just as global aviation approached the cliff.","mistake":"Building a flag challenge on partner politics and thin routes.","lesson":"In airlines, a powerful minority partner still cannot vote against gravity.","book":"hard-things","bookTitle":"The Hard Thing About Hard Things"},{"id":"tigerair-australia","name":"Tigerair Australia","title":"The budget badge is retired","year":"2020","category":"BUSINESS","emoji":"✈️","loss":"Brand retired in 2020","story":"Tigerair Australia gave Virgin Australia a low cost answer to Jetstar and gave price sensitive travellers a striped alternative. It survived safety and service storms to keep a place in domestic skies. Virgin Australia entered administration in the pandemic and new owner Bain simplified the group. Tigerair's certificate was surrendered and the brand retired in 2020.","mistake":"Being the optional brand inside a parent fighting for survival.","lesson":"In a crisis, parents keep the child closest to the core promise. Optional becomes extinct.","book":"good-strategy-bad-strategy","bookTitle":"Good Strategy Bad Strategy"},{"id":"nokscoot","name":"NokScoot","title":"The long haul low cost squeeze","year":"2020","category":"BUSINESS","emoji":"✈️","loss":"Liquidated in 2020","story":"NokScoot joined Thai Nok Air and Singapore's Scoot to fly medium and long haul low cost routes from Bangkok. Widebody cheap flying sounded like Asia's next frontier. Long haul low cost is fragile: fuel, aircraft cost and load factor leave little forgiveness. The pandemic removed the last cushion and the board liquidated NokScoot in 2020.","mistake":"Stretching the low cost model over distances where mistakes compound for hours.","lesson":"The longer the route, the less room there is for a cheap error.","book":"profit-first","bookTitle":"Profit First"},{"id":"montenegro-airlines","name":"Montenegro Airlines","title":"Small state, heavy wings","year":"2020","category":"BUSINESS","emoji":"✈️","loss":"Grounded and bankrupt","story":"Montenegro Airlines carried a tiny nation's flag and tourism hopes with a fleet larger than the home market could feed. State support kept routes alive because connection felt national. Debt and European state aid rules closed around it. The government stopped funding at the end of 2020, flights ceased and bankruptcy followed, with a new airline later created under a different name.","mistake":"Running a national symbol on commercial oxygen without deciding which it was.","lesson":"A country can buy connectivity openly or lose it expensively. Pretending it is profit helps neither.","book":"mighty-fall","bookTitle":"How the Mighty Fall"},{"id":"atlasglobal","name":"AtlasGlobal","title":"The holiday airline files in winter","year":"2020","category":"BUSINESS","emoji":"✈️","loss":"Bankruptcy declared in 2020","story":"AtlasGlobal carried Turkish and European holiday traffic and tried scheduled ambitions from Istanbul. It operated in the crowded space between charter emotion and network discipline. Financial strain led it to suspend flights in 2019, resume briefly, then stop again. Bankruptcy was declared in 2020 as the pandemic approached, ending another leisure airline that lived close to the edge.","mistake":"Expanding ambition while cash stayed seasonal.","lesson":"Tourism revenue has a calendar. Debt does not respect it.","book":"psychology-of-money","bookTitle":"The Psychology of Money"},{"id":"germania","name":"Germania","title":"The green tails disappear","year":"2019","category":"BUSINESS","emoji":"✈️","loss":"Insolvent in 2019","story":"Germania flew German holidaymakers to sun and family routes for decades, independent beside giants and tour brands. Its green tails were familiar at regional airports. Fuel prices, aircraft delays, a strong euro squeeze and failed financing talks hit together. Germania filed for insolvency in February 2019 and grounded flights overnight.","mistake":"Carrying independent scale in a market of giants and tour operator power.","lesson":"Mid sized airlines need either protection, niche or cost advantage. Germania's cushion ran out.","book":"hard-things","bookTitle":"The Hard Thing About Hard Things"},{"id":"adria-airways","name":"Adria Airways","title":"Slovenia loses its wings","year":"2019","category":"BUSINESS","emoji":"✈️","loss":"Bankrupt in 2019","story":"Adria Airways connected Ljubljana to Europe for decades and carried Slovenian identity after independence. Privatisation was meant to give the small flag carrier a commercial owner. The owner lacked depth, aircraft were repossessed and regulators tightened as cash vanished. Adria filed for bankruptcy in 2019 after suspending flights, leaving Slovenia without its flag carrier.","mistake":"Selling a fragile national asset to capital too thin for aviation weather.","lesson":"Due diligence matters most when the buyer promises rescue with confidence and little cash.","book":"principles-dalio","bookTitle":"Principles"},{"id":"aigle-azur","name":"Aigle Azur","title":"France's second airline dissolves","year":"2019","category":"BUSINESS","emoji":"✈️","loss":"Liquidated in 2019","story":"Aigle Azur built strength on routes between France and Algeria and tried to widen into long haul with new partners. It was France's second airline by passengers at its peak. Shareholder conflict, cash shortage and failed rescue bids grounded it in September 2019. Courts liquidated the company after no buyer could take the whole operation.","mistake":"Letting owner disputes fly the plane into the ground.","lesson":"Governance is not a boardroom hobby when payroll and fuel need decisions this week.","book":"hard-things","bookTitle":"The Hard Thing About Hard Things"},{"id":"primera-air","name":"Primera Air","title":"Transatlantic on a shoestring","year":"2018","category":"BUSINESS","emoji":"✈️","loss":"Collapsed in 2018","story":"Primera Air chased cheap transatlantic flights with new narrowbody aircraft and bold base announcements. Travellers loved the fares and the promise of smaller airports. Aircraft delivery delays forced expensive wet leases just as a plane was lost to corrosion repair. Cash snapped and Primera ceased operations in October 2018, even warning passengers not to travel to airports.","mistake":"Expanding routes faster than fleet certainty allowed.","lesson":"In low cost long haul, one missing aircraft is not an inconvenience. It can be the business model missing.","book":"hard-things","bookTitle":"The Hard Thing About Hard Things"},{"id":"flybmi","name":"Flybmi","title":"Regional routes meet Brexit weather","year":"2019","category":"BUSINESS","emoji":"✈️","loss":"Collapsed in 2019","story":"Flybmi, born from British Midland lineage, flew regional routes linking smaller cities to hubs. It survived ownership changes by being useful in the corners of maps. Fuel prices, carbon costs and Brexit uncertainty hit contracts and forward bookings. The airline collapsed in February 2019, stranding passengers and removing links regional airports struggled to replace.","mistake":"Depending on political calm for bookings while costs moved in another currency.","lesson":"Small airlines feel macro shocks in miniature, faster and with less shelter.","book":"black-swan","bookTitle":"The Black Swan"},{"id":"sunedison","name":"SunEdison","title":"The solar empire eats itself","year":"2016","category":"BUSINESS","emoji":"☀️","loss":"Bankrupt in 2016","story":"SunEdison grew from silicon roots into a solar development giant and invented financial structures to own renewable assets. Wall Street rewarded speed while sun power became serious infrastructure. Acquisitions and yieldco complexity piled debt faster than projects could produce trust. When markets questioned the machine, liquidity vanished and SunEdison filed for bankruptcy in 2016 as one of the era's major non bank collapses.","mistake":"Using financial engineering to outrun project cash reality.","lesson":"Complex structures can hide risk from investors for a while. They cannot hide it from maturity dates.","book":"psychology-of-money","bookTitle":"The Psychology of Money"},{"id":"q-cells","name":"Q-Cells","title":"The solar champion in the price war","year":"2012","category":"BUSINESS","emoji":"🔆","loss":"Insolvent in 2012","story":"German Q-Cells helped make solar industrial and became one of the world's largest cell makers when panels still carried premium margins. Policy support and engineering pride built factories fast. Chinese scale and falling panel prices crushed margins while European subsidies cooled. Q-Cells filed for insolvency in 2012 and was sold to Hanwha, a champion absorbed by the cost curve it helped create.","mistake":"Assuming technology leadership would protect commodity manufacturing margins.","lesson":"In solar, the learning curve belongs to whoever survives the price war, not whoever started it.","book":"innovators-dilemma","bookTitle":"The Innovator's Dilemma"},{"id":"suntech-power","name":"Suntech Power","title":"The panel king defaults","year":"2013","category":"BUSINESS","emoji":"☀️","loss":"Main unit bankrupt in 2013","story":"Suntech put Chinese solar manufacturing on the world map and its founder became a green billionaire symbol. Capacity expanded as governments and investors treated sunlight like the next oil rush. Overcapacity smashed prices, debt matured and a fraud linked to financial guarantees damaged trust. Suntech's main Chinese unit entered bankruptcy in 2013 after a bond default.","mistake":"Building global capacity for demand that existed mainly at yesterday's prices.","lesson":"When everyone receives the same subsidy signal, overbuilding becomes the signal.","book":"black-swan","bookTitle":"The Black Swan"},{"id":"evergreen-solar","name":"Evergreen Solar","title":"String ribbon meets cheap panels","year":"2011","category":"BUSINESS","emoji":"☀️","loss":"Bankrupt in 2011","story":"Evergreen Solar promised a cheaper way to make silicon wafers with string ribbon technology and built plants with public support in the US and China. It was a manufacturing answer to an energy dream. Chinese competition and collapsing module prices overwhelmed its cost advantage before scale arrived. Evergreen filed for bankruptcy in 2011 and sold assets, leaving factories as policy arguments.","mistake":"Betting a factory on a cost edge too small for a global price collapse.","lesson":"Process innovation must be dramatically cheaper, not elegantly cheaper.","book":"innovators-dilemma","bookTitle":"The Innovator's Dilemma"},{"id":"abound-solar","name":"Abound Solar","title":"Thin film, thinner cushion","year":"2012","category":"BUSINESS","emoji":"🔆","loss":"Bankrupt in 2012","story":"Abound Solar made cadmium telluride thin film panels in Colorado with federal loan support, aiming at First Solar's path without the same scale. The technology story was credible enough to build a factory. Panel prices fell faster than Abound could cut defects and costs. It halted production, drew political fire over the loan and filed for bankruptcy in 2012.","mistake":"Needing time in a market where prices were falling monthly.","lesson":"If the market price is a cliff, your cost roadmap cannot be a staircase.","book":"profit-first","bookTitle":"Profit First"},{"id":"range-fuels","name":"Range Fuels","title":"Wood chips to nowhere","year":"2011","category":"STARTUP","emoji":"🌲","loss":"Plant sold after failure","story":"Range Fuels promised to turn wood chips into cellulosic ethanol at commercial scale in Georgia, backed by famous venture names and public money. It represented the advanced biofuel hope after corn ethanol doubts. The plant never produced at the promised scale and technology assumptions failed in contact with real biomass. Operations shut and assets were sold in 2011 for a fraction of the investment.","mistake":"Scaling a chemical process before the chemistry had survived repetition.","lesson":"Pilot success is a question. A factory is an answer you must already know.","book":"hard-things","bookTitle":"The Hard Thing About Hard Things"},{"id":"kior","name":"KiOR","title":"The catalyst did not catalyse","year":"2014","category":"STARTUP","emoji":"⛽","loss":"Bankrupt in 2014","story":"KiOR claimed it could turn biomass into crude oil substitutes with a catalyst process, went public and built a Mississippi plant. The story promised fossil fuel chemistry without fossils. Yields fell far below projections, the plant struggled and regulators later alleged investors were misled about how well the technology worked. KiOR filed for bankruptcy in 2014.","mistake":"Selling certainty around yields that the plant had not earned.","lesson":"In process technology, the demo is marketing. The run rate is truth.","book":"bad-blood","bookTitle":"Bad Blood"},{"id":"ask-jeeves","name":"Ask Jeeves","title":"The butler is retired","year":"2006","category":"BUSINESS","emoji":"🔍","loss":"Brand retired in 2006","story":"Ask Jeeves put a polite butler in front of search and invited people to ask questions naturally. In the early web, the character made a technical tool feel friendly. Google made the blank box and better results the habit. Owner IAC retired the Jeeves character in 2006 and renamed the service Ask.com, admitting the mascot could not carry relevance.","mistake":"Letting interface charm stand in for result quality.","lesson":"A friendly front door cannot save a weaker room behind it.","book":"mom-test","bookTitle":"The Mom Test"},{"id":"path","name":"Path","title":"Private by design, empty by default","year":"2018","category":"STARTUP","emoji":"🛤️","loss":"Service shut in 2018","story":"Path limited friends to encourage intimate sharing and designed mobile social with unusual care. It felt like the antidote to Facebook scale and attracted loyal believers. Intimacy limited growth, Facebook copied comfort features and messaging apps took private sharing. After sale of parts to Kakao's ecosystem, Path announced shutdown in 2018.","mistake":"Designing against scale in a business judged by network reach.","lesson":"Constraints can create trust, but investors and users still need a reason the room fills.","book":"mom-test","bookTitle":"The Mom Test"},{"id":"altavista","name":"AltaVista","title":"The search pioneer is switched off","year":"2013","category":"BUSINESS","emoji":"🔎","loss":"Closed by Yahoo in 2013","story":"AltaVista once indexed the web with a power that felt miraculous and helped a generation learn to search. It passed through owners while Google rewrote expectations around speed and relevance. Portal strategies distracted it and the brand became a Yahoo side door. Yahoo closed AltaVista in 2013, ending a pioneer whose name had once been a synonym for finding things online.","mistake":"Treating search as a feature of portals while a rival treated it as the product.","lesson":"Focus is not a slogan when the market rewards one job done relentlessly.","book":"innovators-dilemma","bookTitle":"The Innovator's Dilemma"},{"id":"etoys","name":"eToys","title":"The dotcom toy chest snaps shut","year":"2001","category":"STARTUP","emoji":"🧸","loss":"Bankrupt in 2001","story":"eToys sold toys online with a famous IPO and a mission to beat toy stores at Christmas. It spent heavily on brand, warehouses and the belief that parents would move fast. Logistics and customer acquisition cost more than toy margins could carry, especially after the holiday clock exposed fulfilment strain. eToys filed for bankruptcy in 2001 and became shorthand for dotcom excess.","mistake":"Buying Christmas demand before owning Christmas delivery.","lesson":"Seasonal peaks are audits. Weak operations fail in public and on deadline.","book":"e-myth","bookTitle":"The E-Myth Revisited"},{"id":"sabena","name":"Sabena","title":"Belgium's flag folds","year":"2001","category":"HISTORY","emoji":"✈️","loss":"Bankrupt in 2001","story":"Sabena carried Belgium through the jet age and built an African network rooted in history. It was inefficient, political and beloved in the complicated way national airlines become family. Swissair's own collapse cut support, losses mounted and the September 11 shock hit traffic. Sabena was declared bankrupt in November 2001, one of Europe's early flag carrier funerals.","mistake":"Depending on a sick parent airline for oxygen.","lesson":"In groups, contagion is a route network too.","book":"mighty-fall","bookTitle":"How the Mighty Fall"},{"id":"satyam","name":"Satyam","title":"The confession letter","year":"2009","category":"FRAUD","emoji":"💻","loss":"Founder confessed fraud in 2009","story":"Satyam was one of India's big four IT exporters, serving global clients and symbolising the country's software rise. Its name meant truth, which made the ending harder to forget. In January 2009 founder Ramalinga Raju confessed to inflating profits and cash by about 1.5 billion dollars. The government seized control, clients fled and the company was sold to Tech Mahindra, ending Satyam as an independent name.","mistake":"Letting founder authority and board ceremony replace audit reality.","lesson":"The bigger the trust business, the less charisma should be accepted as evidence.","book":"bad-blood","bookTitle":"Bad Blood"}]);
